  readonly id: string;
  readonly name: string;
  readonly time: string;
  readonly state: TimeState;
}

export interface TimeListProps {
  readonly items: readonly TimeItem[];
  readonly label?: string;
  readonly onSelect?: (item: TimeItem) => void;
}

const STATE_LABEL: Record<TimeState, string> = {
  past: "Passed",
  next: "Next",
  later: "Later",
};

export function TimeList({ items, label = "Today", onSelect }: TimeListProps) {
  return (
    <ol className="time-list" aria-label={label}>
      {items.map((item) => (
        <TimeRow key={item.id} item={item} onSelect={onSelect} />
      ))}
    </ol>
  );
}

interface TimeRowProps {
  readonly item: TimeItem;
  readonly onSelect?: (item: TimeItem) => void;
}

function TimeRow({ item, onSelect }: TimeRowProps) {
  const handleClick = useCallback(() => {
    onSelect?.(item);
  }, [onSelect, item]);

  const handleKeyDown = useCallback(
    (event: KeyboardEvent<HTMLButtonElement>) => {
      if (event.key === "Escape") {
        event.currentTarget.blur();
      }
    },
    [],
  );

  return (
    <li className={`time-list__item time-list__item--${item.state}`}>
      <button
        type="button"
        className="time-list__row"
        aria-current={item.state === "next" ? "time" : undefined}
        onClick={handleClick}
        onKeyDown={handleKeyDown}
      >
        <span className="time-list__name">{item.name}</span>
        <time className="time-list__time">{item.time}</time>
        <span className="time-list__state">{STATE_LABEL[item.state]}</span>
      </button>
    </li>
  );
}

